  const toast = message => { document.querySelector('.ak-toast')?.remove(); const el = document.createElement('div'); el.className = 'ak-toast'; el.textContent = message; document.body.appendChild(el); setTimeout(() => el.remove(), 2400); };
  const sourceBadge = (source, id) => `<span class="ak-badge ${id === 'web' ? 'blue' : id === 'ai' ? 'purple' : id === 'school' ? 'coral' : ''}">${esc(source)}</span>`;
  function filteredLibrary() { return library.filter(q => (!query || (q.title + q.topic + q.chapter).toLowerCase().includes(query.toLowerCase())) && (filterSource === '全部来源' || q.source === filterSource) && (filterType === '全部题型' || q.type === filterType)); }
  function header() { return `<div class="ak-hero"><div><div class="ak-kicker">ASSIGNMENT LIBRARY / 作业知识库</div><h1>把历史题目，变成下一份好作业</h1><p>以教师验证过的题目为底座，混合校内共享、互联网资料与 AI 新题，按比例生成可追溯的章节作业。</p></div><div class="ak-hero-actions"><button class="btn secondary" onclick="akOpenHistory()">修改记录</button><button class="btn primary" onclick="akOpenCreate()">＋ 新建作业</button></div></div><div class="ak-overview"><div class="ak-stat"><span>知识库题目</span><strong>268</strong><em>↑ 本周新增 14 道</em></div><div class="ak-stat"><span>已验证题目</span><strong>214</strong><em>80% 可直接复用</em></div><div class="ak-stat"><span>本章节作业</span><strong>3</strong><em>1 份待核对</em></div><div class="ak-stat"><span>来源覆盖</span><strong>4</strong><em>历史 / 校内 / 网络 / AI</em></div></div><div class="ak-tabs"><button class="ak-tab ${tab === 'knowledge' ? 'active' : ''}" onclick="akTab('knowledge')">知识库与生成</button><button class="ak-tab ${tab === 'assignments' ? 'active' : ''}" onclick="akTab('assignments')">章节作业</button><button class="ak-tab ${tab === 'history' ? 'active' : ''}" onclick="akTab('history')">生成记录</button></div>`; }
  function chapters() { return `<section class="ak-panel"><div class="ak-panel-head"><div><h2>选择作业章节</h2><p>作业会自动关联当前教学大纲和备课内容</p></div><span class="ak-badge">经济学原理 · 2026 秋季</span></div><div class="ak-panel-body"><div class="ak-chapter-rail">${['第一章 · 供求与均衡','第二章 · 弹性与决策','第三章 · 政策与市场','第四章 · 市场结构'].map((x, i) => `<button class="ak-chapter ${activeChapter === x ? 'active' : ''}" onclick="akChapter('${x}')"><b>${x}</b><small>${[10, 6, 4, 8][i]} 道题 · ${i === 0 ? '已完成' : i === 1 ? '草稿' : '待创建'}</small></button>`).join('')}</div></div></section>`; }
  function knowledge() { const rows = filteredLibrary(); return `${chapters()}<div class="ak-layout"><section class="ak-panel"><div class="ak-panel-head"><div><h2>知识库题目</h2><p>筛选并选择可以进入新作业的题目，点击题目可查看来源和使用记录。</p></div><span class="ak-badge">已选 ${selected.size} 道</span></div><div class="ak-panel-body"><div class="ak-search"><input value="${esc(query)}" placeholder="搜索题干、知识点或章节" oninput="akQuery(this.value)"><button class="btn secondary" onclick="akQuery(this.previousElementSibling.value)">搜索</button></div><div class="ak-filter-row"><button class="ak-chip ${filterSource === '全部来源' ? 'active' : ''}" onclick="akSource('全部来源')">全部来源</button>${roles.map(r => `<button class="ak-chip ${filterSource === r.name ? 'active' : ''}" onclick="akSource('${r.name}')">${r.name}</button>`).join('')}</div><div class="ak-filter-row"><button class="ak-chip ${filterType === '全部题型' ? 'active' : ''}" onclick="akType('全部题型')">全部题型</button>${['单选题','判断题','简答题','综合题'].map(x => `<button class="ak-chip ${filterType === x ? 'active' : ''}" onclick="akType('${x}')">${x}</button>`).join('')}</div><div class="ak-source-list">${rows.length ? rows.map(q => `<article class="ak-source-row ${selected.has(q.id) ? 'selected' : ''}" onclick="akSelect('${q.id}')"><input class="ak-source-check" type="checkbox" ${selected.has(q.id) ? 'checked' : ''} onclick="event.stopPropagation();akSelect('${q.id}')"><div><div class="ak-source-title"><b>${esc(q.title)}</b>${sourceBadge(q.source, q.sourceId)}</div><div class="ak-source-meta">${esc(q.type)} · ${esc(q.chapter)} · ${esc(q.topic)} · 难度 ${esc(q.difficulty)}</div></div><div class="ak-source-side"><b>${q.used} 次</b></div></article>`).join('') : '<div class="ak-empty"><strong>没有匹配题目</strong>换一个关键词或放宽来源筛选。</div>'}</div></div></section><aside class="ak-panel ak-builder"><div class="ak-panel-head"><div><h2>生成配方</h2><p>设置来源比例，AI 会按配方组合一份新的作业草稿。</p></div><span class="ak-badge coral">可追溯生成</span></div><div class="ak-panel-body"><div class="ak-recipe">${roles.map(r => `<div class="ak-recipe-item"><div class="ak-recipe-item-top"><b>${r.name}</b><span class="ak-pct" id="akPct-${r.id}">${r.pct}%</span></div><p>${r.detail} · ${r.count ? r.count + ' 道可用题' : '按章节目标生成'}</p><div class="ak-recipe-line"><input type="checkbox" ${r.checked ? 'checked' : ''} onchange="akToggleSource('${r.id}',this.checked)"><input type="range" min="0" max="100" value="${r.pct}" oninput="akPct('${r.id}',this.value)"></div><div class="ak-progress"><i id="akBar-${r.id}" style="width:${r.pct}%;background:${r.color}"></i></div></div>`).join('')}</div><div class="ak-total"><span>来源比例合计</span><strong id="akTotal">100%</strong></div><div class="ak-builder-fields" style="margin-top:12px"><label class="ak-field">题型<select><option>混合题型</option><option>单选 + 判断</option><option>简答 + 综合题</option></select></label><label class="ak-field">题目数量<select><option>10 道</option><option>6 道</option><option>15 道</option></select></label><label class="ak-field">总分<input value="100 分"></label><label class="ak-field">难度<select><option>基础 + 中等</option><option>中等</option><option>中等 + 较难</option></select></label></div><div class="ak-helper" style="margin:13px 0"><span>↗</span><div>历史题目会优先复用，AI 新题会标记为“待核对”，不会直接覆盖已有作业。</div></div><button class="btn primary ak-generate" onclick="akGenerate()">✦ 按此配方生成作业</button></div></aside></div>`; }
  function assignmentsView() { return `${chapters()}<section class="ak-panel"><div class="ak-panel-head"><div><h2>章节作业</h2><p>作业成品、草稿和来源配方集中管理。</p></div><div style="display:flex;gap:7px"><button class="btn secondary" onclick="akImport()">上传已有作业</button><button class="btn primary" onclick="akOpenCreate()">＋ 新建作业</button></div></div><div class="ak-panel-body"><div class="ak-assignments">${assignments.map((a, i) => `<article class="ak-assignment"><div><h3>${a.title}</h3><p>${a.source}</p><div class="ak-assignment-meta"><span class="ak-badge">${a.count} 道题</span><span class="ak-badge">${a.score} 分</span><span class="ak-badge ${a.status === '已确认' ? '' : 'coral'}">${a.status}</span><span class="ak-badge">${a.updated}</span></div></div><div class="ak-assignment-actions"><button class="btn secondary" onclick="akOpenAssignment(${i})">查看</button><button class="btn primary" onclick="akEditAssignment(${i})">编辑</button></div></article>`).join('')}</div></div></section>`; }
  function historyView() { return `${chapters()}<section class="ak-panel"><div class="ak-panel-head"><div><h2>生成与修改记录</h2><p>记录每次作业生成使用的来源配方和教师操作。</p></div><span class="ak-badge">最近 30 天</span></div><div class="ak-panel-body"><div class="ak-history">${[['今天 10:24','生成《第一章 · 供求与均衡 · 课后作业》','历史 45% · 校内 20% · 网络 10% · AI 25% · 10 道题'],['昨天 16:40','采纳 3 道历史题目，忽略 1 道互联网题目','教师林老师 · 第二章 · 弹性与决策'],['9 月 7 日','上传《经济学案例题库.xlsx》并完成解析','解析出 42 道题 · 6 道待核对'],['9 月 6 日','将第 1 题同步到第二章备课和讲义','来源：本人历史作业 · 已保留版本快照']].map(x => `<div class="ak-history-item"><i class="ak-history-dot"></i><div><b>${x[1]}</b><span>${x[0]} · ${x[2]}</span></div></div>`).join('')}</div></div></section>`; }
